#!/usr/bin/env node
// Copies the TipJar ABI out of the Foundry build into the web app.
// The generated file is committed, so `npm run dev` works without a local Foundry build.
// Regenerate with `npm run sync:abi` after changing the contract.
import { readFile, writeFile } from 'node:fs/promises'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const artifact = resolve(root, 'contracts/out/TipJar.sol/TipJar.json')
const target = resolve(root, 'web/lib/tipJarAbi.ts')

let raw
try {
  raw = await readFile(artifact, 'utf8')
} catch {
  console.error(`No build artifact at ${artifact}.\nRun \`npm run build:contracts\` first.`)
  process.exit(1)
}

const { abi } = JSON.parse(raw)
if (!Array.isArray(abi) || abi.length === 0) {
  console.error(`${artifact} has no ABI.`)
  process.exit(1)
}

const banner = [
  '// Generated by `npm run sync:abi` from contracts/out/TipJar.sol/TipJar.json.',
  '// Do not edit by hand — change contracts/src/TipJar.sol and regenerate.',
  '',
  'export const tipJarAbi = ',
].join('\n')

await writeFile(target, `${banner}${JSON.stringify(abi, null, 2)} as const\n`)
console.log(`Wrote ${target} (${abi.length} ABI entries)`)
